def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(([s, e] for s, e in intervals), key=lambda x: (x[0], x[1]))
    merged = []
    for s, e in sorted_intervals:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1][1] = e
        else:
            merged.append([s, e])
    return merged

import heapq

def toposort(nodes, edges):
    unique_edges = set(edges)
    indegree = {node: 0 for node in nodes}
    adjacency = {node: [] for node in nodes}

    for source, destination in unique_edges:
        indegree[destination] += 1
        adjacency[source].append(destination)

    heap = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for destination in adjacency[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                heapq.heappush(heap, destination)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")
    return order

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be a positive integer")
    batches = []
    current = []
    total = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
        if current and total + weight > limit:
            batches.append(current)
            current = []
            total = 0
        current.append(name)
        total += weight
    if current:
        batches.append(current)
    return batches

import re

def parse_env(text):
    key_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f'Invalid line: {raw!r}')
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not key_re.fullmatch(key):
            raise ValueError(f'Invalid key: {key!r}')
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        result[key] = value
    return result

def parse_sse(chunks):
    text = b''.join(chunks).decode('utf-8')
    events = []
    data_lines = []

    for line in text.splitlines():
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    return events
                events.append(data)
                data_lines = []
            continue

        if line.startswith(':'):
            continue

        if ':' in line:
            field, _, value = line.partition(':')
            if value.startswith(' '):
                value = value[1:]
        else:
            field = line
            value = ''

        if field != 'data':
            continue

        data_lines.append(value)

    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("attempt, base, and cap must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0

    fbase = float(base)
    fcap = float(cap)

    if attempt >= 4096:
        return fcap

    logp = math.log(fbase) + attempt * math.log(2.0)
    if logp > math.log(fcap):
        return fcap

    if attempt <= 1023:
        value = fbase * (2.0 ** attempt)
        if math.isfinite(value):
            return min(fcap, value)
    return math.exp(logp)

def fifo_admit(active, queued, budget, slots):
    for reservation in queued:
        if reservation > budget:
            raise ValueError("queued reservation exceeds total budget")

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    i = 0
    while i < len(queued) and remaining_slots > 0 and remaining_budget > 0:
        reservation = queued[i]
        if reservation <= remaining_budget:
            admitted.append(reservation)
            remaining_budget -= reservation
            remaining_slots -= 1
            i += 1
        else:
            break

    remaining = list(queued[i:])
    return admitted, remaining
